    try {
      const mails = await mailLib.fetchRecent(mailCreds(), { days: cfg.mail.days, max: 12, unseenOnly });
      system += '\n\n' + mailLib.promptBlock(mails, { days: cfg.mail.days });
      log(`E-Mail: ${mails.length} Mails gelesen`);
    } catch (err) {
      system += '\n\n' + mailLib.promptBlock([], { error: String(err.message).slice(0, 200), days: cfg.mail.days });
      log(`E-Mail-Abruf fehlgeschlagen: ${String(err.message).slice(0, 120)}`);
    }
  }
  const t0 = Date.now();
  let firstAt = null;

  const seq = cfg.settings.sequential !== false;
  const arranged = healthLib.arrange(orderedChain(), cfg.accounts);
  const chain = arranged.chain.map((id) => {
    const p = P(id);
    const s = cfg.accounts[id];
    const tried = [];
    return {
      id,
      timeoutMs: p.local ? Math.max(90000, cfg.settings.timeoutSec * 1000) : 0,
      get label() { return `${p.name} · ${s.model}`; },
      run: (signal, beat, ctx) => {
        const both = AbortSignal.any([signal, abortSignal]);
        const startedAt = Date.now();
        let seen = false;
        onStatus({ phase: 'asking', provider: p.name, model: s.model });
        return chatStream(p, decrypt(s.key), s.model, clean, system, {
          signal: both, beat,
          onDelta: (text) => {
            if (!seen) { seen = true; recordSpeed(id, Date.now() - startedAt, true); }
            if (ctx && !ctx.claim()) return; // eine andere KI war schneller
            if (!firstAt) { firstAt = Date.now(); onStatus({ phase: 'streaming', provider: p.name, model: s.model, firstMs: firstAt - t0 }); }
            onDelta(text);
          },
        });
      },
      repair: async () => { tried.push(s.model); return refreshModels(id, { exclude: tried }); },
    };
  });
  const byId = (id) => P(id).name;

  try {
    const result = await runWithFallback(chain, {
      log, timeoutMs: cfg.settings.timeoutSec * 1000, maxRetries: seq ? 1 : 2,
      parallel: !seq && cfg.settings.race ? 2 : 1,
      hedgeMs: seq ? 0 : cfg.settings.hedgeSec * 1000,
      onSwitch: (step, failed) => {
        noteFailure(failed.id, failed.err);
        const c = healthLib.classify(failed.err, { local: P(failed.id).local });
        onStatus({ phase: 'switch', provider: byId(step.id), failed: byId(failed.id), reason: c ? healthLib.reasonText(c.kind) : '' });
      },
      onLaunch: (step, reason) => { if (reason === 'slow') onStatus({ phase: 'slow', provider: byId(step.id) }); },
    });
    for (const f of result.failures) { recordSpeed(f.id, f.ms, false); noteFailure(f.id, f.err); }
    if (cfg.accounts[result.used.id] && healthLib.clear(cfg.accounts[result.used.id])) log(`[${P(result.used.id).name}] wieder verfügbar`);
    for (const l of result.losers) if (cfg.accounts[l.id] && l.ms >= 1000 && !(cfg.accounts[l.id].ms >= l.ms)) recordSpeed(l.id, l.ms, true); // abgebrochen: mindestens so langsam
    saveCfg();
    const mem = memory.apply(result.text);
    if (mem.saved.length || mem.forgotten.length) emit('jarvis:state', publicState());
    const pr = gcalLib.extract(result.text);
    let proposals = [];
    if (pr.proposals.length && canPropose && getGcal()) { try { proposals = await makeProposals(pr.proposals); } catch (err) { log(`Terminvorschlag fehlgeschlagen: ${String(err.message).slice(0, 100)}`); } }
    let note = '';
    if (pr.proposals.length && !canPropose) note = '\n\n(Nichts eingetragen: Termine trage ich nur im Jarvis-Fenster am PC ein, nach deiner Bestätigung.)';
    else if (pr.rejected && !proposals.length) note = '\n\n(Ein Terminvorschlag war ungültig und wurde verworfen. Sag es bitte noch einmal genauer.)';
    return { text: (stripTags(pr.clean).trim() + note).trim(), proposals, memorySaved: mem.saved, memoryForgotten: mem.forgotten, pack: invoked?.name || null, by: result.used.label, providerId: result.used.id, fallbacks: result.failures, firstMs: firstAt ? firstAt - t0 : null, totalMs: Date.now() - t0 };
  } catch (err) {
    if (abortSignal.aborted) return { stopped: true };
    for (const f of err.failures || []) { recordSpeed(f.id, f.ms, false); noteFailure(f.id, f.err); }
    saveCfg();
    throw err;
  }
}

// Live-Antwort im Fenster: Stücke gehen per 'chat:delta' an das Fenster
const running = new Map();
ipcMain.handle('chat:send', async (_e, reqId, messages) => {
  const userAbort = new AbortController();
  running.set(reqId, userAbort);
  try {
    return await runChat(messages, {
      canPropose: true,
      abortSignal: userAbort.signal,
      onStatus: (st) => emit('chat:status', { reqId, ...st }),
      onDelta: (text) => emit('chat:delta', { reqId, text }),
    });
  } finally {
    running.delete(reqId);
  }
});
