// Paket als PDF speichern: Anzeige-Seite bauen, drucken, Speichern-Dialog
const escHtml = (v) => String(v ?? '').replace(/[&<>"']/g, (ch) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[ch]));
function packPdfHtml(p) {
  const ex = (p.beispiele || []).map((b) => `<li>${escHtml(b)}</li>`).join('');
  return `<!doctype html><html lang="de"><head><meta charset="utf-8"><title>${escHtml(p.name)}</title><style>
    body{font-family:Segoe UI,Arial,sans-serif;color:#111;margin:0;padding:0 8px;line-height:1.5}
    h1{font-size:22pt;margin:0 0 4px}.cmd{font-family:Consolas,monospace;color:#0a6e8a;font-size:12pt}
    .desc{color:#444;margin:6px 0 14px}h2{font-size:12pt;margin:18px 0 6px;border-bottom:1px solid #ccc;padding-bottom:3px}
    pre{white-space:pre-wrap;font-family:Consolas,monospace;font-size:10pt;background:#f4f7f9;padding:10px;border-radius:4px}
    ul{margin:0;padding-left:18px}.foot{margin-top:24px;font-size:8pt;color:#777}</style></head><body>
    <h1>${escHtml(p.name)}</h1><div class="cmd">${escHtml(p.befehl)}</div>
    <div class="desc">${escHtml(p.beschreibung)}</div>
    ${ex ? `<h2>Beispiele</h2><ul>${ex}</ul>` : ''}
    <h2>Anweisungen</h2><pre>${escHtml(p.instructions)}</pre>
    <div class="foot">Jarvis-Paket · Version ${escHtml(CODE_VERSION)}</div></body></html>`;
}
ipcMain.handle('packs:pdf', async (_e, id) => {
  const p = packs.find((x) => x.id === id && !x.error);
  if (!p) throw new Error('Paket nicht gefunden.');
  if (p.locked) throw new Error('Geschützte Pakete lassen sich nicht als PDF speichern.');
  const r = await dialog.showSaveDialog(win, { title: 'Paket als PDF speichern', defaultPath: `${p.id}.pdf`, filters: [{ name: 'PDF', extensions: ['pdf'] }] });
  if (r.canceled || !r.filePath) return { saved: false };
  const hidden = new BrowserWindow({ show: false, webPreferences: { sandbox: true, contextIsolation: true, javascript: false } });
  try {
    await hidden.loadURL('data:text/html;charset=utf-8,' + encodeURIComponent(packPdfHtml(p)));
    const pdf = await hidden.webContents.printToPDF({ printBackground: true, pageSize: 'A4' });
    fs.writeFileSync(r.filePath, pdf);
  } finally { hidden.destroy(); }
  log(`Paket „${p.name}“ als PDF gespeichert`);
  return { saved: true, file: r.filePath };
});

// ---------- Gedächtnis ----------
ipcMain.handle('memory:add', (_e, text) => { memory.add(text, 'du'); return publicState(); });
ipcMain.handle('memory:remove', (_e, id) => { memory.remove(id); return publicState(); });
ipcMain.handle('memory:clear', () => { memory.clear(); log('Gedächtnis gelöscht'); return publicState(); });

// ---------- Updates ----------
let pendingUpdate = null;
async function checkUpdate(manual = false) {
  try {
    const r = await updater.checkForUpdate({ repo: UPDATE_REPO, currentVersion: CODE_VERSION, shellVersion: BOOT.shellVersion });
    if (r.available) { pendingUpdate = r; log(`Update ${r.version} verfügbar`); }
    emit('update:status', r);
    return r;
  } catch (err) {
    if (manual) throw err;
    return { available: false, reason: err.message };
  }
}
ipcMain.handle('update:check', () => checkUpdate(true));
ipcMain.handle('update:install', async () => {
  if (!pendingUpdate) throw new Error('Kein Update verfügbar.');
  await updater.downloadUpdate({ url: pendingUpdate.url, expectedVersion: pendingUpdate.version, appDir: BOOT.appDir, shellVersion: BOOT.shellVersion });
  log(`Update ${pendingUpdate.version} installiert – starte neu`);
  setTimeout(() => { app.relaunch(); app.exit(0); }, 600);
  return true;
});

// ---------- Fenster ----------
function createWindow() {
  win = new BrowserWindow({
    width: 1240, height: 800, minWidth: 460, minHeight: 560,
    backgroundColor: '#02060b', title: 'Jarvis', autoHideMenuBar: true,
    ...(fs.existsSync(path.join(__dirname, '..', 'assets', 'icon.png')) ? { icon: path.join(__dirname, '..', 'assets', 'icon.png') } : {}),
    webPreferences: { preload: path.join(__dirname, 'preload.js'), contextIsolation: true, nodeIntegration: false, sandbox: true },
  });
  win.loadFile(path.join(__dirname, 'renderer', 'index.html'));
  win.webContents.setWindowOpenHandler(() => ({ action: 'deny' }));
  win.webContents.on('will-navigate', (e) => e.preventDefault());
  win.webContents.once('did-finish-load', () => {
    BOOT.markHealthy();
    // im Hintergrund: Modelllisten auffrischen und nach Updates schauen
    setTimeout(async () => {
      for (const id of activeChain()) if (!P(id).local) refreshModels(id).catch(() => {});
      if (cfg.settings.autoUpdate) { checkUpdate(false); setInterval(() => { if (cfg.settings.autoUpdate) checkUpdate(false); }, 15 * 60 * 1000); }
      if (cfg.settings.wakeWord) wake.set(true, cfg.settings.wakeSens);
      remoteApply().catch(() => {});
      setTimeout(notifyTick, 20000); setInterval(notifyTick, 60000);
      setInterval(() => { if (cfg.remote.enabled && !remote.status().running) remoteApply().catch(() => {}); }, 30000); // Tailscale später gestartet?
    }, 1500);
  });
}

app.whenReady().then(() => {
  cfg = normalize(loadCfg());
  saveCfg();
  chatStore = new ChatStore(path.join(app.getPath('userData'), 'chats.json'));
  remote = new RemoteServer({
    store: chatStore, log,
    answer: (messages, opts) => runChat(messages, opts),
    devices: { get: () => cfg.remote.devices, save: (list) => { cfg.remote.devices = list; saveCfg(); } },
    onChat: (chat) => emit('chats:remote', chat),
  });
  memory = new Memory(path.join(app.getPath('userData'), 'gedaechtnis.json'));
  wake = new WakeWord({
    dir: app.getPath('userData'), log,
    onStatus: (st) => emit('wake:event', { type: 'status', ...st }),
    onHit: (hit) => emit('wake:event', { type: 'hit', ...hit }),
    onHeard: (h) => emit('wake:event', { type: 'heard', ...h }),
  });
  reloadPacks();
  // Nach dem Aufwachen aus dem Ruhezustand (oder Entsperren) startet das Weckwort neu: danach ist das Mikrofon oft weg
  try { powerMonitor.on('resume', () => setTimeout(() => wake?.restart(), 3000)); powerMonitor.on('unlock-screen', () => { if (wake?.state?.state !== 'ready') wake?.restart(); }); } catch { /* egal */ }
  session.defaultSession.setPermissionRequestHandler((_wc, perm, cb) => cb(perm === 'media'));
  session.defaultSession.setPermissionCheckHandler((_wc, perm) => perm === 'media');
  createWindow();
  log(`Jarvis ${CODE_VERSION} gestartet`);
  app.on('activate', () => { if (BrowserWindow.getAllWindows().length === 0) createWindow(); });
});
app.on('window-all-closed', () => { wake?.stop(); remote?.stop(); app.quit(); });
app.on('before-quit', () => { wake?.stop(); remote?.stop(); });

