        ${p.pause ? `<span class="badge pause" title="Jarvis fragt diese KI erst wieder, wenn die Pause vorbei ist">Pause bis ${escapeHtml(p.pause.text)} · ${escapeHtml(p.pause.reason)}</span>` : ''}
