    if (r.available) { showUpdate(r); toast(`Update ${r.version} verfügbar`); } else toast(r.reason || 'Jarvis ist aktuell.');
  } catch (err) { toast(err.message, 5000); }
  els.checkUpdate.disabled = false;
};
