// Zusatzanzeigen im Leitstand-Look: Ring-Anzeigen (CPU, Arbeitsspeicher, Uhrzeit, Datum), Tagesleiste, Hintergrund-Effekte.
// Alles nur Darstellung; die Systemwerte (Auslastung in Prozent) kommen aus dem Hauptprozess, keine Dateien, keine Namen.
(() => {
  const TAU = Math.PI * 2;
  const CYAN = [72, 220, 255];
  const rgba = (c, a) => `rgba(${c[0]},${c[1]},${c[2]},${a})`;
  const reduce = window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;

  function setup(canvas) {
    const dpr = Math.max(1, window.devicePixelRatio || 1);
    const w = canvas.clientWidth || 100; const h = canvas.clientHeight || 100;
    if (canvas.width !== Math.round(w * dpr)) { canvas.width = Math.round(w * dpr); canvas.height = Math.round(h * dpr); }
    const ctx = canvas.getContext('2d'); ctx.setTransform(dpr, 0, 0, dpr, 0, 0); ctx.clearRect(0, 0, w, h);
    return { ctx, w, h };
  }
  // Ring-Anzeige: Wert 0..1 als leuchtender Bogen, Skala, Beschriftung
  function gauge(canvas, { value = 0, big = '', small = '', color = CYAN }) {
    const { ctx, w, h } = setup(canvas); const x = w / 2; const y = h / 2; const R = Math.min(w, h) / 2 - 5;
    ctx.lineCap = 'butt';
    ctx.beginPath(); ctx.arc(x, y, R, 0, TAU); ctx.strokeStyle = rgba(color, 0.18); ctx.lineWidth = 7; ctx.stroke();
    for (let i = 0; i < 40; i++) {
      const a = (i / 40) * TAU - Math.PI / 2; const major = i % 10 === 0;
      ctx.beginPath(); ctx.moveTo(x + Math.cos(a) * (R - 8), y + Math.sin(a) * (R - 8)); ctx.lineTo(x + Math.cos(a) * (R - (major ? 13 : 11)), y + Math.sin(a) * (R - (major ? 13 : 11)));
      ctx.strokeStyle = rgba(color, major ? 0.8 : 0.35); ctx.lineWidth = 1; ctx.stroke();
    }
    const v = Math.max(0, Math.min(1, value));
    if (v > 0.003) {
      ctx.save(); ctx.shadowColor = rgba(color, 0.9); ctx.shadowBlur = 10;
      ctx.beginPath(); ctx.arc(x, y, R, -Math.PI / 2, -Math.PI / 2 + v * TAU); ctx.strokeStyle = rgba(color, 0.95); ctx.lineWidth = 7; ctx.stroke(); ctx.restore();
    }
    ctx.beginPath(); ctx.arc(x, y, R - 18, 0, TAU); ctx.strokeStyle = rgba(color, 0.3); ctx.lineWidth = 1; ctx.stroke();
    ctx.textAlign = 'center'; ctx.textBaseline = 'middle'; ctx.fillStyle = '#e6fbff';
    ctx.font = `600 ${Math.round(R * 0.5)}px "Bahnschrift", "Segoe UI", sans-serif`; ctx.fillText(big, x, y - (small ? 4 : 0));
    if (small) { ctx.fillStyle = rgba(color, 0.9); ctx.font = `${Math.round(R * 0.2)}px "Cascadia Mono", Consolas, monospace`; ctx.fillText(small, x, y + R * 0.38); }
  }

  const $ = (id) => document.getElementById(id);
  const MONTHS = ['Januar', 'Februar', 'März', 'April', 'Mai', 'Juni', 'Juli', 'August', 'September', 'Oktober', 'November', 'Dezember'];
  const stats = { cpu: 0, ram: 0 };
  const hist = { cpu: [], ram: [], tempo: [] };
  try { hist.tempo = (JSON.parse(localStorage.getItem('jarvis.tempo') || '[]') || []).filter(Number.isFinite).slice(-20); } catch { /* egal */ }

  function drawClock() {
    const d = new Date(); const p = (n) => String(n).padStart(2, '0');
    const t = $('ringTime'); if (t) gauge(t, { value: (d.getSeconds() + d.getMilliseconds() / 1000) / 60, big: `${p(d.getHours())}:${p(d.getMinutes())}`, small: p(d.getSeconds()) });
    const dt = $('ringDate'); if (dt) { const dim = new Date(d.getFullYear(), d.getMonth() + 1, 0).getDate(); gauge(dt, { value: d.getDate() / dim, big: String(d.getDate()), small: MONTHS[d.getMonth()].slice(0, 3).toUpperCase() }); }
  }
  function drawStats() {
    const c = $('ringCpu'); if (c) gauge(c, { value: stats.cpu / 100, big: `${Math.round(stats.cpu)}%`, small: 'CPU', color: stats.cpu > 85 ? [255, 120, 90] : CYAN });
    const r = $('ringRam'); if (r) gauge(r, { value: stats.ram / 100, big: `${Math.round(stats.ram)}%`, small: 'RAM', color: stats.ram > 90 ? [255, 120, 90] : CYAN });
  }
  async function pollStats() {
    try { const s = await window.jarvis.getStats(); if (s) { stats.cpu = s.cpu; stats.ram = s.ram; hist.cpu.push(s.cpu); hist.ram.push(s.ram); if (hist.cpu.length > 60) { hist.cpu.shift(); hist.ram.shift(); } drawStats(); drawKurven(); } } catch { /* egal */ }
  }

  // Kurven: letzte Antwortzeiten der KI, CPU- und RAM-Verlauf (leuchtende Linien mit Fläche)
  function spark(ctx, x, y, w, h, vals, max, color, label, last) {
    ctx.fillStyle = rgba(color, 0.9); ctx.font = '10px "Cascadia Mono", Consolas, monospace'; ctx.textBaseline = 'top'; ctx.textAlign = 'left'; ctx.fillText(label, x, y);
    ctx.textAlign = 'right'; ctx.fillStyle = '#e6fbff'; ctx.fillText(last, x + w, y);
    const top = y + 14; const hh = h - 14;
    ctx.strokeStyle = rgba(color, 0.18); ctx.lineWidth = 1; ctx.beginPath(); ctx.moveTo(x, top + hh - 0.5); ctx.lineTo(x + w, top + hh - 0.5); ctx.stroke();
    if (vals.length < 2) { ctx.fillStyle = rgba(color, 0.5); ctx.textAlign = 'left'; ctx.fillText(vals.length ? '·' : 'noch keine Werte', x, top + hh / 2 - 5); return; }
    const pts = vals.map((v, i) => [x + (i / (vals.length - 1)) * w, top + hh - Math.min(1, v / max) * (hh - 2) - 1]);
    const fillG = ctx.createLinearGradient(0, top, 0, top + hh); fillG.addColorStop(0, rgba(color, 0.32)); fillG.addColorStop(1, rgba(color, 0));
    ctx.beginPath(); ctx.moveTo(pts[0][0], top + hh); pts.forEach((p) => ctx.lineTo(p[0], p[1])); ctx.lineTo(pts[pts.length - 1][0], top + hh); ctx.closePath(); ctx.fillStyle = fillG; ctx.fill();
    ctx.save(); ctx.shadowColor = rgba(color, 0.9); ctx.shadowBlur = 6; ctx.strokeStyle = rgba(color, 1); ctx.lineWidth = 1.5; ctx.beginPath(); pts.forEach((p, i) => (i ? ctx.lineTo(p[0], p[1]) : ctx.moveTo(p[0], p[1]))); ctx.stroke(); ctx.restore();
    const e = pts[pts.length - 1]; ctx.fillStyle = '#fff'; ctx.beginPath(); ctx.arc(e[0], e[1], 2.2, 0, TAU); ctx.fill();
  }
  function drawKurven() {
    const cv = $('kvCv'); if (!cv || !cv.clientWidth) return;
    const { ctx, w, h } = setup(cv); const rowH = Math.floor(h / 3);
    const t = hist.tempo; const lastT = t.length ? `${(t[t.length - 1] / 1000).toFixed(2).replace('.', ',')} s` : '–';
    const tMax = Math.max(3000, ...t);
    spark(ctx, 2, 0, w - 4, rowH - 4, t, tMax, [255, 206, 96], 'ANTWORTZEIT', lastT);
    spark(ctx, 2, rowH, w - 4, rowH - 4, hist.cpu, 100, CYAN, 'CPU', hist.cpu.length ? `${Math.round(hist.cpu[hist.cpu.length - 1])}%` : '–');
    spark(ctx, 2, rowH * 2, w - 4, rowH - 4, hist.ram, 100, [96, 240, 200], 'RAM', hist.ram.length ? `${Math.round(hist.ram[hist.ram.length - 1])}%` : '–');
  }
  window.pushTempo = (ms) => {
    if (!Number.isFinite(ms)) return;
    hist.tempo.push(ms); if (hist.tempo.length > 20) hist.tempo.shift();
    try { localStorage.setItem('jarvis.tempo', JSON.stringify(hist.tempo)); } catch { /* egal */ }
    drawKurven();
  };

  // Schlagzeilen (öffentlicher Feed, nur wenn eingeschaltet)
  async function drawNews() {
    const el = $('news'); if (!el) return;
    let n; try { n = await window.jarvis.getNews(); } catch { n = { enabled: true, error: 'Nicht erreichbar' }; }
    if (!n || n.enabled === false) { el.classList.add('hidden'); el.innerHTML = ''; return; }
    el.classList.remove('hidden');
    if (n.error) { el.innerHTML = `<h4>Schlagzeilen</h4><p class="news-err">${esc(n.error)}</p>`; return; }
    el.innerHTML = `<h4>Schlagzeilen<small>${esc(n.source)}${n.stale ? ' · alt' : ''}</small></h4><ul>${(n.items || []).slice(0, 4).map((i) => `<li><button data-url="${esc(i.link)}" title="Im Browser öffnen">${esc(i.title)}</button></li>`).join('')}</ul>`;
  }
  window.refreshNews = drawNews;
  document.addEventListener('click', (e) => { const b = e.target.closest?.('#news button[data-url]'); if (b) window.jarvis.openExternal(b.dataset.url); });
  const WX_ICON = {
    sun: '<circle cx="12" cy="12" r="4.2"/><path d="M12 2.5v3M12 18.5v3M2.5 12h3M18.5 12h3M5.3 5.3l2.1 2.1M16.6 16.6l2.1 2.1M18.7 5.3l-2.1 2.1M7.4 16.6l-2.1 2.1"/>',
    cloud: '<path d="M7 18.5h10a4 4 0 0 0 .6-7.95A5.5 5.5 0 0 0 7.1 9.4 4.6 4.6 0 0 0 7 18.5z"/>',
    rain: '<path d="M7 15h10a3.8 3.8 0 0 0 .5-7.55A5.2 5.2 0 0 0 7.2 6.6 4.2 4.2 0 0 0 7 15z"/><path d="M8.5 18l-1 2.5M12.5 18l-1 2.5M16.5 18l-1 2.5"/>',
    snow: '<path d="M7 14.5h10a3.8 3.8 0 0 0 .5-7.55A5.2 5.2 0 0 0 7.2 6.1 4.2 4.2 0 0 0 7 14.5z"/><path d="M8.5 18.5h.01M12.5 19.5h.01M16.5 18.5h.01M10.5 21h.01M14.5 21h.01"/>',
    fog: '<path d="M5 9h14M3.5 13h17M6 17h12"/>',
    storm: '<path d="M7 14h10a3.8 3.8 0 0 0 .5-7.55A5.2 5.2 0 0 0 7.2 5.6 4.2 4.2 0 0 0 7 14z"/><path d="M12.5 14l-2.5 4h3l-2 4"/>',
  };
  const wxSvg = (k) => `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${WX_ICON[k] || WX_ICON.cloud}</svg>`;
  const esc = (t) => String(t ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const WD = ['So', 'Mo', 'Di', 'Mi', 'Do', 'Fr', 'Sa'];
  async function drawWeather() {
    const el = $('wx'); if (!el) return;
    let w; try { w = await window.jarvis.getWeather(); } catch { w = { error: 'Nicht erreichbar' }; }
    if (!w || !w.set) { el.innerHTML = '<div class="wx-empty">Wetter<br><small>Ort einstellen</small></div>'; return; }
    if (w.error) { el.innerHTML = `<div class="wx-empty">Wetter<br><small>${esc(w.error)}</small></div>`; return; }
    const days = (w.days || []).slice(1, 4).map((d) => {
      const [y, m, dd] = String(d.date).split('-').map(Number);
      return `<div class="wx-day"><span>${WD[new Date(y, m - 1, dd).getDay()]}</span>${wxSvg(d.icon)}<b>${esc(d.max)}°</b><i>${esc(d.min)}°</i></div>`;
    }).join('');
    el.innerHTML = `<div class="wx-now">${wxSvg(w.icon)}<div><strong>${esc(w.temp)}°</strong><small>${esc(w.text)}</small></div></div>`
      + `<div class="wx-place">${esc(w.place)}${w.stale ? ' · alt' : ''}</div>`
      + `<div class="wx-meta">Wind ${esc(w.wind)} km/h · Feuchte ${esc(w.humidity)}%</div><div class="wx-days">${days}</div>`;
  }
  window.refreshWeather = drawWeather;
  function dayStrip() {
    const el = $('dayStrip'); if (!el) return;
    const d = new Date(); const dim = new Date(d.getFullYear(), d.getMonth() + 1, 0).getDate();
    el.innerHTML = Array.from({ length: dim }, (_, i) => `<span${i + 1 === d.getDate() ? ' class="today"' : ''}>${String(i + 1).padStart(2, '0')}</span>`).join('');
  }

  // Hintergrund: schwebende Lichtpunkte + feine Leiterbahnen (einmal gezeichnet)
  function fx() {
    const cv = $('fx'); if (!cv) return;
    const ctx = cv.getContext('2d'); let W = 0; let H = 0; let dots = []; let traces = null;
    function resize() {
      const dpr = Math.max(1, window.devicePixelRatio || 1); W = innerWidth; H = innerHeight;
      cv.width = Math.round(W * dpr); cv.height = Math.round(H * dpr); ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      const n = Math.round(Math.min(70, W * H / 22000));
      dots = Array.from({ length: n }, () => ({ x: Math.random() * W, y: Math.random() * H, vx: (Math.random() - 0.5) * 6, vy: -2 - Math.random() * 7, r: 0.6 + Math.random() * 1.5, a: 0.12 + Math.random() * 0.4, ph: Math.random() * 6 }));
      traces = document.createElement('canvas'); traces.width = W; traces.height = H;
      const t = traces.getContext('2d'); t.lineWidth = 1; t.strokeStyle = 'rgba(72,220,255,.13)'; t.fillStyle = 'rgba(72,220,255,.4)';
      const rnd = (a, b) => a + Math.random() * (b - a);
      for (let i = 0; i < 16; i++) {
        const left = i % 2 === 0; let x = left ? rnd(0, W * 0.08) : rnd(W * 0.92, W); let y = rnd(H * 0.08, H * 0.95);
        t.beginPath(); t.moveTo(x, y);
        for (let s = 0; s < 4; s++) { const dx = (left ? 1 : -1) * rnd(30, W * 0.09); x += dx; t.lineTo(x, y); y += rnd(-90, 90); t.lineTo(x, y); }
        t.stroke(); t.beginPath(); t.arc(x, y, 2.5, 0, TAU); t.fill();
      }
    }
    resize(); addEventListener('resize', resize);
    let last = performance.now();
    function frame(now) {
      const dt = Math.min(0.05, (now - last) / 1000); last = now;
      ctx.clearRect(0, 0, W, H); if (traces) ctx.drawImage(traces, 0, 0);
      for (const d of dots) {
        d.x += d.vx * dt; d.y += d.vy * dt; if (d.y < -4) { d.y = H + 4; d.x = Math.random() * W; } if (d.x < -4) d.x = W + 4; if (d.x > W + 4) d.x = -4;
        ctx.beginPath(); ctx.arc(d.x, d.y, d.r, 0, TAU); ctx.fillStyle = `rgba(110,232,255,${d.a * (0.65 + 0.35 * Math.sin(now / 900 + d.ph))})`; ctx.fill();
      }
      if (!reduce) requestAnimationFrame(frame);
    }
    requestAnimationFrame(frame);
  }

  function start() {
    dayStrip(); drawClock(); drawStats(); fx();
    setInterval(drawClock, 1000); setInterval(pollStats, 2500); setInterval(dayStrip, 3600000); pollStats();
    drawWeather(); setInterval(drawWeather, 20 * 60 * 1000);
    drawKurven(); drawNews(); setInterval(drawNews, 20 * 60 * 1000);
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', start); else start();
})();

files.router.js:
// Jarvis Router: verteilt Anfragen an die verbundenen KIs.
// Wiederholt nur bei vorübergehenden Fehlern, wechselt danach zur nächsten KI.
// Bei Live-Antworten wird nur gewechselt, solange noch kein Wort angezeigt wurde.

const MAX_WAIT_MS = 10000; // länger wartet Jarvis nie auf dieselbe KI
const RETRYABLE_STATUS = new Set([408, 429, 500, 502, 503, 504, 529]);

class ProviderError extends Error {
  constructor(message, { status = null, retryAfterMs = null, network = false, timeout = false, streamed = false, modelGone = false, lost = false, limit = false } = {}) {
    super(message);
    this.name = 'ProviderError';
    this.status = status;
    this.retryAfterMs = retryAfterMs;
    this.network = network;
    this.timeout = timeout;
    this.streamed = streamed; // es wurde schon Text angezeigt
    this.modelGone = modelGone; // Modell abgeschaltet / nicht gefunden
    this.lost = lost; // eine andere KI war schneller
    this.limit = limit; // Nutzungslimit / Guthaben aufgebraucht: Warten lohnt nicht
  }
}

function isRetryable(err) {
  if (!(err instanceof ProviderError) || err.streamed || err.lost) return false;
  if (err.limit) return false; // Limit leer: sofort die nächste KI
  if (err.timeout) return false; // lieber gleich wechseln als nochmal lange warten
  if (err.network) return true;
  if (err.status === 429 && err.retryAfterMs != null && err.retryAfterMs > MAX_WAIT_MS) return false;
  return err.status != null && RETRYABLE_STATUS.has(err.status);
}

function parseRetryAfter(value, now = Date.now()) {
  if (value == null || value === '') return null;
  const secs = Number(value);
  if (Number.isFinite(secs)) return Math.max(0, secs * 1000);
  const date = Date.parse(value);
  if (!Number.isNaN(date)) return Math.max(0, date - now);
  return null;
}

function backoffDelay(attempt, { baseMs = 800, maxMs = 15000, random = Math.random } = {}) {
  const exp = Math.min(maxMs, baseMs * 2 ** attempt);
  return Math.round(exp / 2 + random() * (exp / 2));
}

const defaultSleep = (ms) => new Promise((r) => setTimeout(r, ms));

// timeoutMs = Zeit bis zum ersten Lebenszeichen; jedes beat() startet die Uhr neu (für Live-Antworten)
async function callOnce(fn, timeoutMs) {
  const ctrl = new AbortController();
  let timer = setTimeout(() => ctrl.abort(), timeoutMs);
  const beat = () => { clearTimeout(timer); timer = setTimeout(() => ctrl.abort(), timeoutMs); };
  try {
    return await fn(ctrl.signal, beat);
  } catch (err) {
    if (err instanceof ProviderError && !ctrl.signal.aborted) throw err;
    if (ctrl.signal.aborted || err?.name === 'AbortError') {
      throw new ProviderError(`Zeitüberschreitung nach ${Math.round(timeoutMs / 1000)} s`, { timeout: true, streamed: !!err?.streamed });
    }
    throw new ProviderError(`Netzwerkfehler: ${err?.message || err}`, { network: true });
  } finally {
    clearTimeout(timer);
  }
}

async function callWithRetry(fn, { maxRetries = 2, timeoutMs = 60000, sleep = defaultSleep, random = Math.random, onRetry } = {}) {
  let attempt = 0;
  for (;;) {
    try {
      return await callOnce(fn, timeoutMs);
    } catch (err) {
      if (!isRetryable(err) || attempt >= maxRetries) throw err;
      const wait = err.retryAfterMs != null ? Math.min(err.retryAfterMs, MAX_WAIT_MS) : backoffDelay(attempt, { random });
      onRetry?.({ attempt: attempt + 1, waitMs: wait, error: err });
      await sleep(wait);
      attempt++;
    }
  }
}

/**
 * chain: [{ id, label, run: (signal, beat, ctx) => Promise<string>, repair?: (err) => Promise<boolean> }]
 * ctx.claim(): vor dem ersten angezeigten Text aufrufen – nur die KI, die zuerst "claimt", gewinnt;
 *   alle anderen laufenden KIs werden sofort abgebrochen. false = zu spät, Text verwerfen.
 * repair: darf z. B. ein abgeschaltetes Modell ersetzen; true = gleiche KI nochmal versuchen
 *
 * opts.parallel  Wie viele KIs gleichzeitig starten (1 = nacheinander)
 * opts.hedgeMs   Antwortet noch keine KI nach dieser Zeit, wird zusätzlich die nächste gestartet (0 = aus)
 * opts.maxActive Obergrenze gleichzeitig laufender Anfragen
 */
function runWithFallback(chain, opts = {}) {
  const { log = () => {}, onSwitch = () => {}, onLaunch = () => {}, parallel = 1, hedgeMs = 0, maxActive = 3 } = opts;
  if (!chain.length) return Promise.reject(new ProviderError('Keine KI verbunden. Öffne die Einstellungen und verbinde mindestens einen Anbieter.'));
  const failures = [];
  const active = new Set();
  let next = 0;
  let winner = null;
  let settled = false;
  let hedgeTimer = null;
  const losers = [];

  return new Promise((resolve, reject) => {
    const finish = (fn, value) => { if (settled) return; settled = true; clearTimeout(hedgeTimer); fn(value); };

    function claim(att) {
      if (winner && winner !== att) return false;
      if (!winner) {
        winner = att;
        clearTimeout(hedgeTimer);
        for (const other of active) if (other !== att) { other.lost = true; losers.push({ id: other.step.id, ms: Date.now() - other.startedAt }); other.ctrl.abort(); }
      }
      return true;
    }

    async function runAttempt(att) {
      const { step } = att;
      const wrapped = (signal, beat) => {
        if (att.lost) throw new ProviderError('Eine andere KI war schneller', { lost: true });
        return step.run(AbortSignal.any([signal, att.ctrl.signal]), beat, { claim: () => claim(att) });
      };
      let repaired = false;
      for (;;) {
        try {
          return await callWithRetry(wrapped, {
            ...opts,
            timeoutMs: step.timeoutMs || opts.timeoutMs,
            onRetry: ({ attempt, waitMs, error }) => log(`[${step.label}] Versuch ${attempt} in ${waitMs} ms – ${error.message}`),
          });
        } catch (err) {
          if (att.lost) throw new ProviderError('Eine andere KI war schneller', { lost: true });
          if (err.streamed) throw err; // schon Text angezeigt -> nicht doppelt antworten
          if (!repaired && err.modelGone && step.repair) {
            repaired = true;
            try {
              if (await step.repair(err)) { log(`[${step.label.split(' · ')[0]}] Modell veraltet – auf neues Modell umgestellt`); continue; }
            } catch { /* Reparatur fehlgeschlagen */ }
          }
          throw err;
        }
      }
    }

    function scheduleHedge() {
      clearTimeout(hedgeTimer);
      if (!(hedgeMs > 0) || winner || settled || next >= chain.length) return;
      hedgeTimer = setTimeout(() => {
        if (winner || settled || next >= chain.length) return;
        if (active.size < maxActive) launch('slow'); else scheduleHedge();
      }, hedgeMs);
    }

    function launch(reason) {
      const step = chain[next++];
      const att = { step, ctrl: new AbortController(), lost: false, startedAt: Date.now() };
      active.add(att);
      if (reason === 'failed' && failures.length) onSwitch(step, failures[failures.length - 1]);
      onLaunch(step, reason, failures[failures.length - 1]);
      runAttempt(att).then((text) => onDone(att, text), (err) => onFail(att, err));
      scheduleHedge();
    }

    function onDone(att, text) {
      if (settled || (winner && winner !== att)) return;
      claim(att);
      active.delete(att);
      log(failures.length ? `[${att.step.label}] hat übernommen` : `[${att.step.label}] hat geantwortet`);
      finish(resolve, { text, used: att.step, failures, losers, ms: Date.now() - att.startedAt });
    }

    function onFail(att, err) {
      active.delete(att);
      if (settled || err.lost || att.lost) return;
      if (err.streamed) {
        log(`[${att.step.label}] mitten in der Antwort abgebrochen: ${err.message}`);
        finish(reject, err);
        return;
      }
      log(`[${att.step.label}] fehlgeschlagen: ${err.message}`);
      failures.push({ id: att.step.id, label: att.step.label, error: err.message, ms: Date.now() - att.startedAt, err });
      if (winner) return;
      if (next < chain.length && (active.size === 0 || active.size < parallel)) { launch('failed'); return; }
      if (active.size === 0) {
        const summary = failures.map((f) => `• ${f.label}: ${f.error}`).join('\n');
        const e = new ProviderError(`Keine KI konnte antworten:\n${summary}`);
        e.failures = failures;
        finish(reject, e);
      }
    }

    const first = Math.max(1, Math.min(parallel, chain.length));
    for (let i = 0; i < first; i++) launch(i === 0 ? 'start' : 'parallel');
  });
}

module.exports = { ProviderError, isRetryable, parseRetryAfter, backoffDelay, callWithRetry, runWithFallback, RETRYABLE_STATUS };

files.speed.js:
// Misst, wie schnell jede KI das erste Wort liefert, und sortiert danach.
const DEFAULT_MS = 2500;

function record(old, ms, ok = true) {
  const sample = ok ? ms : Math.max(ms, 12000);
  if (!Number.isFinite(old)) return Math.round(sample);
  return Math.round(old * 0.6 + sample * 0.4);
}

/** Stabil: ähnlich schnelle KIs (gleiche 1,5-Sekunden-Stufe) behalten deine Reihenfolge. */
function sortBySpeed(ids, msOf) {
  return ids
    .map((id, i) => ({ id, i, bucket: Math.round((msOf(id) ?? DEFAULT_MS) / 1500) }))
    .sort((a, b) => a.bucket - b.bucket || a.i - b.i)
    .map((x) => x.id);
}

module.exports = { record, sortBySpeed, DEFAULT_MS };

files.updater.js:
// Selbst-Update über GitHub-Releases.
// Ein Release enthält die Datei "jarvis-app.json" = der komplette App-Code als Text.
// Der neue Code landet in %APPDATA%\Jarvis\app\<version>\ und wird beim Neustart geladen.
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

function cmpVersion(a, b) {
  const pa = String(a).replace(/^v/, '').split('.').map(Number);
  const pb = String(b).replace(/^v/, '').split('.').map(Number);
  for (let i = 0; i < 3; i++) {
    const d = (pa[i] || 0) - (pb[i] || 0);
    if (d) return Math.sign(d);
  }
  return 0;
}

const GH_HEADERS = { 'user-agent': 'Jarvis-Updater', accept: 'application/vnd.github+json' };

// Quelle 1: Datei release/version.json im Repo (einfach per Hochladen aktualisierbar)
async function fromRepoFile(repo, fetchImpl) {
  const base = `https://raw.githubusercontent.com/${repo}/main/release`;
  const res = await fetchImpl(`${base}/version.json?t=${Date.now()}`, { headers: { 'user-agent': 'Jarvis-Updater' }, signal: AbortSignal.timeout(10000) });
  if (!res.ok) return null;
  const j = await res.json();
  return j?.version ? { version: String(j.version).replace(/^v/, ''), notes: String(j.notes || ''), url: `${base}/jarvis-app.json?v=${j.version}` } : null;
}
// Quelle 2: GitHub-Release mit Asset jarvis-app.json
async function fromRelease(repo, fetchImpl) {
  const res = await fetchImpl(`https://api.github.com/repos/${repo}/releases/latest`, { headers: GH_HEADERS, signal: AbortSignal.timeout(10000) });
  if (!res.ok) return null;
  const rel = await res.json();
  const asset = (rel.assets || []).find((a) => a.name === 'jarvis-app.json');
  const version = String(rel.tag_name || '').replace(/^v/, '');
  return version && asset ? { version, notes: String(rel.body || ''), url: asset.browser_download_url } : null;
}

async function checkForUpdate({ repo, currentVersion, shellVersion, fetchImpl = fetch }) {
  const found = (await Promise.allSettled([fromRepoFile(repo, fetchImpl), fromRelease(repo, fetchImpl)]))
    .map((r) => (r.status === 'fulfilled' ? r.value : null)).filter(Boolean);
  if (!found.length) return { available: false, reason: 'Noch keine Updates veröffentlicht.' };
  const best = found.sort((a, b) => cmpVersion(b.version, a.version))[0];
  if (cmpVersion(best.version, currentVersion) <= 0) return { available: false, version: best.version, reason: 'Jarvis ist aktuell.' };
  return { available: true, version: best.version, notes: best.notes.slice(0, 2000), url: best.url, shellVersion };
}

function safeJoin(root, rel) {
  if (typeof rel !== 'string' || !rel || rel.includes('\0') || path.isAbsolute(rel) || /^[a-z]:/i.test(rel)) throw new Error(`Ungültiger Pfad: ${rel}`);
  const full = path.resolve(root, rel);
  if (!full.startsWith(path.resolve(root) + path.sep)) throw new Error(`Ungültiger Pfad: ${rel}`);
  return full;
}

/** Lädt und entpackt das Update. Gibt den Ordner zurück. */
async function downloadUpdate({ url, expectedVersion, appDir, shellVersion, fetchImpl = fetch }) {
  const res = await fetchImpl(url, { headers: { 'user-agent': 'Jarvis-Updater' }, redirect: 'follow', signal: AbortSignal.timeout(60000) });
  if (!res.ok) throw new Error(`Download fehlgeschlagen (${res.status})`);
  const raw = await res.text();
  const pkg = JSON.parse(raw);
  if (pkg.format !== 1 || !pkg.files || typeof pkg.files !== 'object') throw new Error('Update-Datei hat ein unbekanntes Format.');
  if (pkg.version !== expectedVersion) throw new Error('Versionsnummer passt nicht.');
  if (pkg.minShell && cmpVersion(shellVersion, pkg.minShell) < 0) {
    throw new Error(`Dieses Update braucht eine neue Grundinstallation (mind. ${pkg.minShell}). Bitte einmal neu herunterladen.`);
  }
  // Prüfsumme gegen Übertragungsfehler
  const hash = crypto.createHash('sha256').update(JSON.stringify(pkg.files)).digest('hex');
  if (pkg.sha256 && pkg.sha256 !== hash) throw new Error('Update-Datei ist beschädigt.');
  if (!pkg.files['main.js']) throw new Error('Update unvollständig.');

  const target = path.join(appDir, pkg.version);
  const tmp = `${target}.tmp-${Date.now()}`;
  for (const [rel, content] of Object.entries(pkg.files)) {
    const file = safeJoin(tmp, rel);
    fs.mkdirSync(path.dirname(file), { recursive: true });
    fs.writeFileSync(file, typeof content === 'string' ? content : Buffer.from(content.base64, 'base64'));
  }
  fs.rmSync(target, { recursive: true, force: true });
  fs.renameSync(tmp, target);
  fs.writeFileSync(path.join(appDir, 'current.json'), JSON.stringify({ version: pkg.version, dir: target, tries: 0 }));
  return target;
}

module.exports = { cmpVersion, checkForUpdate, downloadUpdate, safeJoin };

files.wake.js:
// "Hey Jarvis": lokale Weckwort-Erkennung mit der eingebauten Windows-Spracherkennung (System.Speech).
// Läuft komplett offline auf dem PC. Erst nach dem Weckwort nimmt Jarvis deine Frage auf.
const { spawn } = require('child_process');
const fs = require('fs');
const path = require('path');

const THRESHOLD = { low: 0.88, mid: 0.8, high: 0.7 };
const START_TIMEOUT_MS = 25000; // so lange darf der Start dauern
const SILENCE_TIMEOUT_MS = 100000; // das Skript meldet sich alle 30 s; länger still = hängt
const MAX_RESTARTS = 8; const MAX_RETRIES = 20;
const PERMANENT = /Keine Windows-Spracherkennung/;

// PowerShell-Skript: erkennt nur die Weckwort-Sätze; eine Diktat-Grammatik fängt alles andere ab (weniger Fehlalarme).
const SCRIPT = String.raw`
param([double]$Min = 0.8)
$ErrorActionPreference = 'Stop'
[Console]::OutputEncoding = [Text.Encoding]::UTF8
try {
  Add-Type -AssemblyName System.Speech
  $recs = [System.Speech.Recognition.SpeechRecognitionEngine]::InstalledRecognizers()
  if ($recs.Count -eq 0) { [Console]::Out.WriteLine('ERROR:Keine Windows-Spracherkennung installiert. Windows-Einstellungen > Zeit und Sprache > Sprache > Deutsch > Optionen > Spracherkennung hinzufügen.'); exit 2 }
  $info = $recs | Where-Object { $_.Culture.Name -eq 'de-DE' } | Select-Object -First 1
  if (-not $info) { $info = $recs | Where-Object { $_.Culture.Name -like 'de-*' } | Select-Object -First 1 }
  if (-not $info) { $info = $recs | Where-Object { $_.Culture.Name -like 'en-*' } | Select-Object -First 1 }
  if (-not $info) { $info = $recs[0] }
  $eng = New-Object System.Speech.Recognition.SpeechRecognitionEngine($info)
  $choices = New-Object System.Speech.Recognition.Choices
  $choices.Add([string[]]@('Hey Jarvis', 'Hei Jarvis', 'Hallo Jarvis', 'Okay Jarvis', 'Jarvis'))
  $gb = New-Object System.Speech.Recognition.GrammarBuilder($choices)
  $gb.Culture = $info.Culture
  $wake = New-Object System.Speech.Recognition.Grammar($gb)
  $wake.Name = 'wake'
  $eng.LoadGrammar($wake)
  try { $dict = New-Object System.Speech.Recognition.DictationGrammar; $dict.Name = 'other'; $dict.Weight = 0.3; $eng.LoadGrammar($dict) } catch { }
  $eng.SetInputToDefaultAudioDevice()
  [Console]::Out.WriteLine('READY:' + $info.Culture.Name)
  while ($true) {
    $r = $eng.Recognize([TimeSpan]::FromSeconds(30))
    [Console]::Out.WriteLine('ALIVE')
    if ($r -ne $null) {
      $c = [Math]::Round($r.Confidence, 2)
      [Console]::Out.WriteLine('HEARD:' + $c + ':' + $r.Text)
      $named = ($r.Grammar.Name -eq 'wake' -and $r.Confidence -ge $Min)
      $fuzzy = ($r.Text -match '(?i)ar[vw][iy]s' -and $r.Confidence -ge ($Min - 0.25))
      if ($named -or $fuzzy) { [Console]::Out.WriteLine('WAKE:' + $c + ':' + $r.Text) }
    }
  }
} catch {
  [Console]::Out.WriteLine('ERROR:' + $_.Exception.Message)
  exit 1
}
`;

class WakeWord {
  constructor({ dir, onStatus, onHit, onHeard, log = () => {}, platform = process.platform, spawnImpl = spawn }) {
    Object.assign(this, { dir, onStatus, onHit, onHeard, log, platform, spawnImpl });
    this.proc = null; this.wanted = false; this.sens = 'mid'; this.restarts = 0; this.retries = 0; this.state = { state: 'off' }; this.timer = null; this.retryTimer = null; this.lastHit = 0;
  }
  status(s) { this.state = s; this.onStatus?.(s); }

  set(enabled, sens = this.sens) {
    const changed = sens !== this.sens;
    this.sens = THRESHOLD[sens] ? sens : 'mid';
    this.wanted = !!enabled;
    if (!this.wanted) return this.stop();
    if (this.platform !== 'win32') return this.status({ state: 'unsupported', detail: '„Hey Jarvis“ gibt es nur unter Windows.' });
    if (this.proc && changed) { this.stop(); }
    if (!this.proc) { this.restarts = 0; this.retries = 0; clearTimeout(this.retryTimer); this.start(); }
  }

  /** Neu starten, z. B. nach dem Aufwachen des PCs oder wenn das Mikrofon gewechselt wurde. */
  restart() {
    if (!this.wanted || this.platform !== 'win32') return;
    this.log('Weckwort wird neu gestartet');
    clearTimeout(this.retryTimer); this.restarts = 0; this.retries = 0;
    const p = this.proc; this.proc = null; this.clearWatch();
    try { p?.kill(); } catch { /* egal */ }
    this.start();
  }

  clearWatch() { clearTimeout(this.timer); this.timer = null; }
  // Wächter: kommt der Start nicht voran oder verstummt das Skript, wird es beendet (der Exit-Handler startet dann neu)
  watch(ms, why) {
    this.clearWatch();
    const proc = this.proc;
    this.timer = setTimeout(() => { if (this.proc === proc && proc) { this.log(`Weckwort: ${why}, Neustart`); try { proc.kill(); } catch { /* egal */ } } }, ms);
    this.timer.unref?.();
  }

  start() {
    const file = path.join(this.dir, 'jarvis-weckwort.ps1');
    fs.writeFileSync(file, '﻿' + SCRIPT); // BOM, damit Umlaute in PowerShell 5 stimmen
    this.status({ state: 'starting' });
    const proc = this.spawnImpl('powershell.exe', ['-NoProfile', '-NonInteractive', '-ExecutionPolicy', 'Bypass', '-File', file, '-Min', String(THRESHOLD[this.sens])], { windowsHide: true });
    this.proc = proc;
    this.watch(START_TIMEOUT_MS, 'Start dauert zu lange');
    let buf = '';
    let fatal = false; let retryable = null;
    proc.stdout.setEncoding('utf8');
    proc.stdout.on('data', (d) => {
      buf += d;
      if (this.state.state === 'ready') this.watch(SILENCE_TIMEOUT_MS, 'keine Lebenszeichen');
      let i;
      while ((i = buf.indexOf('\n')) !== -1) {
        const line = buf.slice(0, i).trim(); buf = buf.slice(i + 1);
        if (line === 'ALIVE') continue;
        if (line.startsWith('READY:')) { this.restarts = 0; this.retries = 0; this.watch(SILENCE_TIMEOUT_MS, 'keine Lebenszeichen'); this.status({ state: 'ready', detail: line.slice(6) }); this.log(`Weckwort bereit (${line.slice(6)})`); }
        else if (line.startsWith('HEARD:')) { const [, conf, ...text] = line.split(':'); this.onHeard?.({ confidence: Number(conf), text: text.join(':').slice(0, 80) }); }
        else if (line.startsWith('WAKE:')) {
          if (Date.now() - this.lastHit < 1500) continue; // Doppeltreffer ignorieren
          this.lastHit = Date.now();
          const [, conf, ...text] = line.split(':');
          this.log(`Weckwort erkannt (${conf})`);
          this.onHit?.({ confidence: Number(conf), text: text.join(':') });
        } else if (line.startsWith('ERROR:')) {
          const msg = line.slice(6); this.log(`Weckwort-Fehler: ${msg}`);
          if (PERMANENT.test(msg)) { fatal = true; this.status({ state: 'error', detail: msg }); } else retryable = msg; // z. B. Mikrofon weg: später erneut versuchen
        }
      }
    });
    proc.stderr?.on('data', (d) => this.log(`Weckwort: ${String(d).trim().slice(0, 200)}`));
    proc.on('error', (err) => { fatal = true; this.status({ state: 'error', detail: `PowerShell nicht startbar: ${err.message}` }); });
    proc.on('exit', () => {
      if (this.proc !== proc) return;
      this.proc = null; this.clearWatch();
      if (!this.wanted) return;
      if (fatal) return;
      if (retryable) {
        // Fehler, die vergehen können (Mikrofon abgesteckt, Gerät gesperrt): mit wachsenden Pausen erneut versuchen
        if (this.retries >= MAX_RETRIES) { this.status({ state: 'error', detail: `${retryable} (Aufgegeben nach ${MAX_RETRIES} Versuchen. Mikrofon prüfen und das Weckwort aus- und wieder einschalten.)` }); return; }
        const wait = Math.min(60, 5 * 2 ** Math.min(this.retries, 4)); this.retries++;
        this.status({ state: 'retry', detail: `${retryable}\nNeuer Versuch in ${wait} Sekunden (${this.retries}/${MAX_RETRIES}).` });
        this.retryTimer = setTimeout(() => { if (this.wanted && !this.proc) this.start(); }, wait * 1000); this.retryTimer.unref?.();
        return;
      }
      if (this.restarts >= MAX_RESTARTS) { this.status({ state: 'error', detail: 'Weckwort-Erkennung ist mehrfach abgestürzt. Weckwort aus- und wieder einschalten.' }); return; }
      this.restarts++;
      const t = setTimeout(() => { if (this.wanted && !this.proc) this.start(); }, Math.min(30000, 1500 * this.restarts)); t.unref?.();
    });
  }

  stop() {
    this.wanted = false; clearTimeout(this.retryTimer); this.clearWatch();
    const p = this.proc; this.proc = null;
    try { p?.kill(); } catch { /* egal */ }
    this.status({ state: 'off' });
  }
}

module.exports = { WakeWord, THRESHOLD, SCRIPT };

